with remaining_keys as (select location, id from departments intersect select location, id from departments where location in ('Chiang Mai', 'Bangkok', 'Tokyo')), verified as (select s.* from departments s join remaining_keys k on s.location = k.location and s.id = k.id) select case when budget >= 4260000 then 'PREMIUM' else 'STANDARD' end as budget_tier, location, round(sum(budget) / nullif(count(case when location = 'Bangkok' then 1 end), 0), 2) as budget_per_bangkok, round(avg(budget), 2) as avg_budget, sort_array(collect_set(dept_name)) as dept_name_list, stddev_samp(budget) as budget_stddev, grouping(case when budget >= 4260000 then 'PREMIUM' else 'STANDARD' end) as gid from verified group by cube (case when budget >= 4260000 then 'PREMIUM' else 'STANDARD' end, location) order by budget_stddev desc
